patch.after:
def make_joint_rate(epoch, requested_rate, record, *, diagnostic, spin_cpu=False):
    if spin_cpu:
        if not diagnostic:
            raise ValueError('Spin CPU probe requires the explicit rate timing probe')
        from rate_spin_cpu_probe import JointRateSpinCpuProbe
        rate_type = JointRateSpinCpuProbe
    else:
        rate_type = JointRateTimingProbe if diagnostic else JointRate
    rate = rate_type(epoch, requested_rate, record)
    if diagnostic and not spin_cpu:
        # Diagnostic history only: keep the latest sample. The parent probe
        # appends every TimingSample and nothing reads the history.
        rate.timings = collections.deque(rate.timings, maxlen=1)
    return rate
